#version 300
uniform shader image;
uniform float2 size;
uniform float2 layer;
uniform float3x3 fromLayer;
uniform float3x3 toLayer;
uniform float4 screen;
uniform float time;
float2 amzCoord;
float4 amzOutput;
float2 amzScreenNorm() { float2 p=amzCoord-screen.xy; return float2(p.x/screen.z,1.0-p.y/screen.w); }
float2 amzLayerNorm() { float3 p=toLayer*float3(amzCoord,1.0); float2 n=p.xy/p.z/layer; return float2(n.x,1.0-n.y); }
float2 amzLayerCenter() { float3 p=fromLayer*float3(layer*.5,1.0); return p.xy/p.z-screen.xy; }
float4x4 amzRowMatrix(float3x3 m) { return float4x4(m[0].x,m[1].x,0.0,m[2].x, m[0].y,m[1].y,0.0,m[2].y, 0.0,0.0,1.0,0.0, m[0].z,m[1].z,0.0,m[2].z); }
float4x4 amzLayerToScreen() {
    float3x3 toNorm=float3x3(1.0/screen.z,0.0,0.0, 0.0,-1.0/screen.w,0.0,-screen.x/screen.z,1.0+screen.y/screen.w,1.0);
    float3x3 toPixels=float3x3(layer.x,0.0,0.0, 0.0,-layer.y,0.0, 0.0,layer.y,1.0);
    return amzRowMatrix(toNorm*fromLayer*toPixels);
}
float4x4 amzScreenToLayer() {
    float3x3 toPixels=float3x3(screen.z,0.0,0.0, 0.0,-screen.w,0.0, screen.x,screen.y+screen.w,1.0);
    float3x3 toNorm=float3x3(1.0/layer.x,0.0,0.0, 0.0,-1.0/layer.y,0.0,0.0,1.0,1.0);
    return amzRowMatrix(toNorm*toLayer*toPixels);
}
float2 getTexSize(float2 v) { return v; }
int amzIntMax(int a,int b) { return int(max(float(a),float(b))); }
int amzIntMin(int a,int b) { return int(min(float(a),float(b))); }
int amzIntAbs(int a) { return int(abs(float(a))); }
int amzIntClamp(int a,int b,int c) { return int(clamp(float(a),float(b),float(c))); }
uniform float2 amzVelocity,amzPivot,amzScale;
uniform float amzAngularVelocity,amzScaleVelocity,amzStartTime,amzEndTime;

struct AC_ImageInfo { int texture; float2 amzLocal_size; };
const float3x3 labPlaneInverse=float3x3(1);
float4x4 amzQuaternion(float4 q) {
    q /= max(length(q),0.000001);
    float x=q.x,y=q.y,z=q.z,w=q.w;
    return float4x4(1-2*(y*y+z*z),2*(x*y+w*z),2*(x*z-w*y),0,
                    2*(x*y-w*z),1-2*(x*x+z*z),2*(y*z+w*x),0,
                    2*(x*z+w*y),2*(y*z-w*x),1-2*(x*x+y*y),0,0,0,0,1);
}
const int amzPass=0;
uniform float amzIteration;
float4 amzSample_inputImg(float2 uv) { return float4(image.eval(((float2(uv.x,1.0-uv.y)*screen.zw+screen.xy)/1.0))); }
float4 amzTexture(int tex,float2 uv) { if(tex==0) return amzSample_inputImg(uv);return float4(0.0); }
float4 amzTexture(int tex,float2 uv,float bias){return amzTexture(tex,uv);}
uniform float amzp_brightnessAmp;
uniform float amzp_colorAmp;
uniform float amzp_frequency;
uniform float amzp_smoothRandom;
uniform float amzp_bias;
uniform float amzp_phase;
uniform float amzp_flickerMode;
uniform float amzp_frameBased;
uniform float amzp_strobeAmount;
uniform float amzp_strobeWidth;
uniform float amzp_redAmount;
uniform float amzp_greenAmount;
uniform float amzp_blueAmount;
uniform float amzp_baseBrightness;
uniform float amzp_contrast;
uniform float amzp_saturation;
uniform float amzp_seed;
uniform float amzp_blend;


        float hash(float n) {
            return fract(sin(n * 12.9898 + amzp_seed * 78.233) * 43758.5453123);
        }

        float hash2(float n, float s) {
            return fract(sin(n * 17.371 + s * 91.713 + amzp_seed * 41.17) * 24634.6345);
        }

        float smoothNoise(float x) {
            float i = floor(x);
            float f = fract(x);

            float a = hash(i);
            float b = hash(i + 1.0);

            f = f * f * (3.0 - 2.0 * f);

            return mix(a, b, f);
        }

        float3 saturateColor(float3 col, float sat) {
            float grey = dot(col, float3(0.2126, 0.7152, 0.0722));
            return mix(float3(grey), col, sat);
        }

        float3 applyContrast(float3 col, float con) {
            return (col - 0.5) * con + 0.5;
        }

        float getFlicker(float t) {
            float timeValue = t * amzp_frequency + amzp_phase * 100.0;

            float steppedTime = floor(timeValue);
            float mixedTime = mix(timeValue, steppedTime, amzp_frameBased);

            float hardRand = hash(floor(timeValue));
            float softRand = smoothNoise(timeValue);

            float randValue = mix(hardRand, softRand, amzp_smoothRandom);

            float pulseValue = sin(timeValue * 6.2831853) * 0.5 + 0.5;

            float randomPulse = pulseValue * randValue;

            float finalFlicker = randValue;

            if (int(amzp_flickerMode) == 0) {
                finalFlicker = hash(floor(mixedTime));
            }
            else if (int(amzp_flickerMode) == 1) {
                finalFlicker = smoothNoise(timeValue);
            }
            else if (int(amzp_flickerMode) == 2) {
                finalFlicker = pulseValue;
            }
            else if (int(amzp_flickerMode) == 3) {
                finalFlicker = randomPulse;
            }

            finalFlicker = mix(finalFlicker, smoothNoise(timeValue), amzp_smoothRandom * 0.5);

            return finalFlicker;
        }

        void amzRender() {
            float2 uv = amzScreenNorm();
            float t = time;

            float4 src = amzTexture(0, uv);
            float3 col = src.rgb;

            float flicker = getFlicker(t);



            float centered = (flicker - 0.5) * 2.0;
            centered += amzp_bias;
            centered = clamp(centered, -2.0, 2.0);

            float brightnessMult = 1.0 + centered * amzp_brightnessAmp;



            float strobePhase = fract((t * amzp_frequency) + amzp_phase);
            float strobeMask = step(strobePhase, amzp_strobeWidth);
            float strobeMult = mix(1.0, strobeMask * 2.0, amzp_strobeAmount);

            brightnessMult *= strobeMult;

            col *= amzp_baseBrightness;
            col *= brightnessMult;



            float rt = t * amzp_frequency + 13.1 + amzp_phase * 50.0;
            float gt = t * amzp_frequency + 37.7 + amzp_phase * 80.0;
            float bt = t * amzp_frequency + 91.3 + amzp_phase * 120.0;

            float rNoise = mix(hash2(floor(rt), 1.0), smoothNoise(rt), amzp_smoothRandom);
            float gNoise = mix(hash2(floor(gt), 2.0), smoothNoise(gt), amzp_smoothRandom);
            float bNoise = mix(hash2(floor(bt), 3.0), smoothNoise(bt), amzp_smoothRandom);

            float rFlick = 1.0 + ((rNoise - 0.5) * 2.0) * amzp_colorAmp * amzp_redAmount;
            float gFlick = 1.0 + ((gNoise - 0.5) * 2.0) * amzp_colorAmp * amzp_greenAmount;
            float bFlick = 1.0 + ((bNoise - 0.5) * 2.0) * amzp_colorAmp * amzp_blueAmount;

            col *= float3(rFlick, gFlick, bFlick);

            col = applyContrast(col, amzp_contrast);
            col = saturateColor(col, amzp_saturation);
            col = clamp(col, 0.0, 1.0);

            float4 result = float4(col, src.a);

            amzOutput = mix(src, result, amzp_blend);
        }


half4 main(float2 coord) { amzCoord=coord*1.0; amzOutput=float4(0.0); amzRender(); return half4(amzOutput); }

